import java.util.*;

class Solution {
  private Integer prev;
  private int run, best;
  private final List<Integer> modes = new ArrayList<>();

  public int[] findMode(TreeNode root) {
    inorder(root);
    return modes.stream().mapToInt(Integer::intValue).toArray();
  }

  // inorder visits equal values consecutively
  private void inorder(TreeNode node) {
    if (node == null) return;
    inorder(node.left);
    run = prev != null && prev == node.val ? run + 1 : 1;
    prev = node.val;
    if (run > best) {
      best = run;
      modes.clear();
    }
    if (run == best) modes.add(node.val);
    inorder(node.right);
  }
}
